import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import EventSalesFilterForm from './EventSalesFilterForm';
import EventSalesInputForm from './EventSalesInputForm';
import EventSalesResult from './EventSalesResult';
import { phonePlans } from '../config/phonePlanConfig';
import { defaultEventConfig } from '../config/eventConfig';
import SaveConsultationButton from '../components/SaveConsultationButton';  // 상담 저장 및 공유 버튼 컴포넌트

export default function EventSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    category: '',
    dataFilter: '',
    planId: '',
    others: '',
    deviceModel: '',
    deviceVariant: '',
    devicePrice: '',
    discountType: '',
    subsidyAmount: '',
    partialPayment: '',
    pensionApply: '',
    installments: 24,
  });
  const [result, setResult] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  // 계산 가능 여부: Senior의 경우 pensionApply 선택까지 필수
  const canCalc = Boolean(
    values.category &&
    values.planId &&
    values.deviceModel &&
    values.deviceVariant &&
    values.discountType &&
    (values.category !== '5G 시니어 (만 65세 이상)' || values.pensionApply)
  );

  const handleFilterChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: value,
      ...(name === 'planId' && { others: phonePlans.find(p => p.id === value)?.others || '' }),
      ...(name === 'category' && { planId: '', dataFilter: '', others: '', pensionApply: '' }),
    }));
    setResult(null);
    setRecommendedDiscount('');
  };

  const handleInputChange = (name, value) => {
    setValues(prev => ({ ...prev, [name]: value }));
    setResult(null);
    setRecommendedDiscount('');
  };

  const handleCalculate = () => {
    if (!canCalc) return;

    const isSenior = values.category === '5G 시니어 (만 65세 이상)';
    const hasPension = values.pensionApply === 'yes';
    const monthlyRate = defaultEventConfig.taxRate / 12;

    const selectedPlan = phonePlans.find(p => p.id === values.planId);
    const planCost = selectedPlan ? selectedPlan.monthlyFee : 0;
    const pensionDiscount = isSenior && hasPension ? Math.min(planCost * 0.5, 12100) : 0;

    const basePrice = defaultEventConfig.devices
      .find(d => d.id === values.deviceModel)
      ?.variants.find(v => v.id === values.deviceVariant)?.price || 0;
    const principal = basePrice - Number(values.partialPayment || 0);
    const principalAfterSub = principal - Number(values.subsidyAmount || 0);

    const deviceCostContract = values.installments > 0
      ? Math.ceil((principal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -values.installments)))
      : 0;
    const deviceCostSubsidy = values.installments > 0
      ? Math.ceil((principalAfterSub * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -values.installments)))
      : 0;

    const rawContractPlan = planCost * 0.75;
    const rawSubsidyPlan = planCost;

        // 월 총 납부액 계산 (계약할인/공시지원금 시나리오)
    const planAfterContract = planCost * 0.75;
    const planAfterSubsidy = planCost;
    const planAfterContractWithPension = planAfterContract - pensionDiscount;
    const planAfterSubsidyWithPension = planAfterSubsidy - pensionDiscount;

    const deviceInstallmentContract = deviceCostContract;
    const deviceInstallmentSubsidy = deviceCostSubsidy;

    const totalPayment = values.discountType === 'contract'
      ? planAfterContractWithPension + deviceInstallmentContract
      : planAfterSubsidyWithPension + deviceInstallmentSubsidy;

    // 절감액 로직
    const totalSubsidyScenario = planCost + deviceInstallmentSubsidy;
    const totalContractScenario = planCost * 0.75 + deviceInstallmentContract;
    const diff = values.discountType === 'contract'
      ? totalSubsidyScenario - totalContractScenario
      : totalContractScenario - totalSubsidyScenario;

    const deviceInstallment = values.discountType === 'contract'
      ? deviceInstallmentContract
      : deviceInstallmentSubsidy;

 values.discountType === 'contract' ? deviceCostContract : deviceCostSubsidy;

                setResult({
          monthlyPlanCost: planCost,
          deviceInstallment,
          totalPayment,
          savings: diff,
          appliedPensionDiscount: pensionDiscount,
          discountType: values.discountType,
          pensionApply: values.pensionApply,
        });
    setRecommendedDiscount(
      totalContractScenario < totalSubsidyScenario ? '요금할인' : '공시 지원금'
    );
  };

  return (
   <div className="flex justify-center py-6 bg-gray-100">   
      {/* 캡처 대상: 계산기 전체 박스에 ID 부여 */}
      <div
        id="calculator-container"
         className="w-full max-w-lg bg-white p-6 rounded-lg shadow-md"
         >
        <h1 className="text-2xl font-bold mb-2 text-center">KT 이벤트 계산기</h1>
        <p className="text-center text-red-600 text-sm mb-4">
          주의! 본 견적은 가견적이오니, 정확한 견적은 필히 추가 확인 바랍니다.
        </p>
        <EventSalesFilterForm values={values} onChange={handleFilterChange} />
        <EventSalesInputForm
          values={values}
          onChange={handleInputChange}
          others={values.others}
          recommendedDiscount={recommendedDiscount}
        />
        <button
          onClick={handleCalculate}
          disabled={!canCalc}
          className={`w-full py-2 rounded-md mb-3 transition ${
            canCalc
              ? 'bg-blue-600 text-white hover:bg-blue-700'
              : 'bg-gray-300 text-gray-500 cursor-not-allowed'
          }`}
        >
          계산하기
        </button>
        {result && (
       <>
          <EventSalesResult
            monthlyPlanCost={result.monthlyPlanCost}
            deviceInstallment={result.deviceInstallment}
            totalPayment={result.totalPayment}
            savings={result.savings}
            appliedPensionDiscount={result.appliedPensionDiscount}
            discountType={values.discountType}
            pensionApply={values.pensionApply}
             />
             <div className="mt-4">
               <SaveConsultationButton formData={values} />
             </div>
           </>

        )}
        <button
          onClick={() => navigate('/')}
          className="w-full bg-gray-200 text-gray-700 py-2 rounded-md mt-2 hover:bg-gray-300"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
