/* File: src/calculators/EventSalesResult.jsx */
import React from 'react';

export default function EventSalesResult({
  monthlyPlanCost,
  deviceInstallment,
  totalPayment,
  savings,
  appliedPensionDiscount,
  pensionApply,
  discountType,
}) {
  // 기본값
  const mpc = monthlyPlanCost ?? 0;
  const di = deviceInstallment ?? 0;
  const tp = totalPayment ?? 0;
  const sv = savings ?? 0;
  const pd = appliedPensionDiscount ?? 0;

  // 절감액 표시 기호 및 절대값
  const sign = sv > 0 ? '+' : sv < 0 ? '-' : '';
  const absSv = Math.abs(sv);

  // 절감액 라벨
  const label =
    discountType === 'subsidy'
      ? '공시 지원금 절감액'
      : discountType === 'contract'
        ? '요금할인 절감액'
        : '절감액';

  return (
    <div className="mt-4 p-4 bg-gray-100 rounded space-y-2">
      <p className="text-lg">
        월 요금제: <strong>{mpc.toLocaleString()}원</strong>
      </p>

      {/* 시니어 기초연금 적용 시 표시 */}
      {pensionApply === 'yes' && (
        <p className="text-lg text-indigo-600">
          기초연금 할인액: <strong>{pd.toLocaleString()}원</strong>
        </p>
      )}

      <p className="text-lg">
        단말 할부 대금: <strong>{di.toLocaleString()}원</strong>
      </p>

      <p className="text-lg">
        월 총 납부 예상 금액: <strong>{tp.toLocaleString()}원</strong>
      </p>

      {/* 할인 타입에 따른 절감액 */}
     <p className={`text-lg ${savings >= 0 ? 'text-green-600' : 'text-red-600'}`}>
     {label}: {sign}{Math.abs(savings).toLocaleString()}원
    </p>

      <p className="mt-2 text-base font-bold text-red-500">
        주의! 본 견적은 대략적인 결과 값입니다.
      </p>
    </div>
  );
}
