// File: src/components/SaveConsultationButton.jsx
import React, { useState } from 'react';
import ShareButton from './ShareButton';
import { saveConsultationLocal } from '../utils/localStorageApi';

/**
 * 상담 저장하기 버튼, 고객 정보 입력 폼, 및 공유 버튼
 * 서버 호출 제거 → 로컬스토리지에만 저장
 * 오늘 날짜 자동 표시 기능 포함
 */
export default function SaveConsultationButton({ formData }) {
  const today = new Date().toLocaleDateString('ko-CA'); // 한국 표준시 기준 YYYY-MM-DD

  // 고객 정보 상태
  const [customerType, setCustomerType] = useState('');
  const [customerName, setCustomerName] = useState('');
  const [customerPhone, setCustomerPhone] = useState('');
  // 저장된 상담 데이터
  const [savedData, setSavedData] = useState(null);

  // UI 상태
  const [showForm, setShowForm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // 폼 열기
  const handleStart = () => {
    setShowForm(true);
    setError(null);
    setSavedData(null);
  };

  // 로컬에 저장
  const handleSubmit = () => {
    if (!customerType || !customerName || !customerPhone) {
      setError('구분, 이름, 전화번호를 모두 입력해주세요.');
      return;
    }
    setLoading(true);
    setError(null);

    const payload = {
      ...formData,
      customerType,
      customerName,
      customerPhone,
      savedAt: today,
    };

    try {
      saveConsultationLocal(payload);
      setSavedData(payload);
      setShowForm(false);
    } catch (err) {
      console.error('로컬 저장 오류:', err);
      setError('로컬 저장 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-2 border rounded bg-white max-w-md">
      {/* 초기 버튼 */}
      {!showForm && !savedData && (
        <button
          onClick={handleStart}
          className="w-full py-2 bg-blue-600 hover:bg-blue-700 text-white rounded"
        >
          상담 저장하기
        </button>
      )}

      {/* 입력 폼 */}
      {showForm && (
        <div className="flex flex-col space-y-0">
          <div className="flex justify-between items-center">
            <span className="text-sm font-medium">날짜:</span>
            <span className="text-sm">{today}</span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm font-medium">구분:</span>
            <select
              value={customerType}
              onChange={e => setCustomerType(e.target.value)}
              className="flex-1 border rounded p-1 ml-1 text-sm"
            >
              <option value="">선택하세요</option>
              <option value="타사">타사</option>
              <option value="신규">신규</option>
              <option value="기변">기변</option>
              <option value="기변">약정갱신</option>
            </select>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm font-medium">이름:</span>
            <input
              type="text"
              value={customerName}
              onChange={e => setCustomerName(e.target.value)}
              className="flex-1 border rounded p-1 ml-1 text-sm"
              placeholder="홍길동"
            />
          </div>
          <div className="flex justify-between items-center">
            <span className="text-sm font-medium">전화번호:</span>
            <input
              type="tel"
              value={customerPhone}
              onChange={e => setCustomerPhone(e.target.value)}
              className="flex-1 border rounded p-1 ml-1 text-sm"
              placeholder="010-1234-5678"
            />
          </div>
          {error && <p className="text-red-600 text-xs mt-1">{error}</p>}
          <div className="flex space-x-1 mt-1">
            <button
              onClick={handleSubmit}
              disabled={loading}
              className="flex-1 py-1 bg-green-600 hover:bg-green-700 text-white rounded text-sm"
            >
              {loading ? '저장...' : '확인'}
            </button>
            <button
              onClick={() => setShowForm(false)}
              disabled={loading}
              className="flex-1 py-1 bg-gray-300 hover:bg-gray-400 text-gray-800 rounded text-sm"
            >
              취소
            </button>
          </div>
        </div>
      )}

      {/* 저장 후 데이터 및 공유 */}
      {savedData && (
        <div className="mt-1 space-y-0 text-sm">
          <div className="flex justify-between"><span>날짜:</span><span>{savedData.savedAt}</span></div>
          <div className="flex justify-between"><span>구분:</span><span>{savedData.customerType}</span></div>
          <div className="flex justify-between"><span>이름:</span><span>{savedData.customerName}</span></div>
          <div className="flex justify-between"><span>전화번호:</span><span>{savedData.customerPhone}</span></div>
         {/* calculator-container 영역만 캡처 */} 
        <ShareButton  selector="#calculator-container"  className="my-3"
        />
        </div>
      )}
    </div>
  );
}
